// HasKindEvaluations applies the HasEdge predicate on the "kind_evaluations" edge.
func HasKindEvaluations() predicate.WorkInsightEvaluationSnapshot {
	return predicate.WorkInsightEvaluationSnapshot(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, KindEvaluationsTable, KindEvaluationsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasKindEvaluationsWith applies the HasEdge predicate on the "kind_evaluations" edge with a given conditions (other predicates).
func HasKindEvaluationsWith(preds ...predicate.WorkInsightKindEvaluationSnapshot) predicate.WorkInsightEvaluationSnapshot {
	return predicate.WorkInsightEvaluationSnapshot(func(s *sql.Selector) {
		step := newKindEvaluationsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasLatestEvidence applies the HasEdge predicate on the "latest_evidence" edge.
func HasLatestEvidence() predicate.WorkInsightEvaluationSnapshot {
	return predicate.WorkInsightEvaluationSnapshot(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, LatestEvidenceTable, LatestEvidenceColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasLatestEvidenceWith applies the HasEdge predicate on the "latest_evidence" edge with a given conditions (other predicates).
func HasLatestEvidenceWith(preds ...predicate.Evidence) predicate.WorkInsightEvaluationSnapshot {
	return predicate.WorkInsightEvaluationSnapshot(func(s *sql.Selector) {
		step := newLatestEvidenceStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.WorkInsightEvaluationSnapshot) predicate.WorkInsightEvaluationSnapshot {
	return predicate.WorkInsightEvaluationSnapshot(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.WorkInsightEvaluationSnapshot) predicate.WorkInsightEvaluationSnapshot {
	return predicate.WorkInsightEvaluationSnapshot(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.WorkInsightEvaluationSnapshot) predicate.WorkInsightEvaluationSnapshot {
	return predicate.WorkInsightEvaluationSnapshot(sql.NotPredicates(p))
}
